    s=json.loads((PUBLIC/'summary.json').read_text());export=json.loads((PUBLIC/'ledger-export.json').read_text());pref=json.loads((SRC/'preflight.json').read_text());change=100*(s['new_continuation_calls']/s['old_continuation_calls']-1);expected=100*s['descriptive_expected_relative_reduction']['display_float'];lines=[];add=lambda line='':lines.append(line)
    add('# H3bn: expected-cost optimization increases realized membership cost');add();add(f"**The actual-call primary is falsified.** Weighted-tree continuation uses 2,913 paid membership calls versus 2,725 for the original first-lex trees: **188 more calls, a {change:.6f}% increase**. The frozen primary required at most 2,588 calls, equivalent to at least a 5% reduction. Meanwhile the specified posterior expected-cost objective decreases by {expected:.6f}%. These are different outcomes; the expected reduction is not evidence of a realized benefit.");add();add('![Expected versus actual query cost](../../../../results/research/loki/h3bn/expected-versus-actual-cost.png)');add()
    add('| Method | Actual continuation calls | Total policy calls including 5,577 inherited MAP calls | Exact cases |');add('|---|---:|---:|---:|');add('| BP AdamW | Not measured | Not measured | Not measured |');add('| Original first-lex hybrid, archived H3bm | 2,725 | 8,302 | 1,354/1,408 |');add('| Posterior-weighted optimal trees, new execution | 2,913 | 8,490 | 1,354/1,408 |');add()
    add('The actual primary is evaluated by the integer comparison `100 * new_calls <= 95 * 2725`; the maximum passing integer is 2,588. The observed left side is 291,300 versus 258,875 on the right. Expected costs, per-truth differences and cumulative policy costs are descriptive. Preserving exactly 1,354 identified cases is a required correctness invariant, not a separate scientific success.');add()
    add('| Truth | Exact cases /64, unchanged | Original continuation | Weighted continuation | Difference |');add('|---:|---:|---:|---:|---:|')
